const stats = $input.all().map(item => item.json);

// Filtra vídeos ativos
const ativos = stats.filter(v => v.status === "Ativo");
const totalVideos = stats.length;
const topVideo = ativos[0] || { title: "Nenhum", views: 0 };

// Função segura para cortar string sem quebrar pares de surrogates (emojis)
const sliceTitle = (str, limit) => {
  if (!str) return "";
  const arr = [...str];
  return arr.length > limit ? arr.slice(0, limit - 3).join("") + "..." : str;
};

// Média de views e engajamento dos TOP 5
const top5 = ativos.slice(0, 5);
let sumViews = 0;
let sumEngagement = 0;
top5.forEach(v => {
  sumViews += v.views || 0;
  sumEngagement += v.engagement || 0;
});
const avgViewsTop5 = top5.length ? Math.round(sumViews / top5.length) : 0;
const avgEngageTop5 = top5.length ? (sumEngagement / top5.length).toFixed(2) : "0.00";

// Lista dos TOP 3
let top3List = "";
top5.slice(0, 3).forEach((v, i) => {
  const emojiNumber = ["1️⃣", "2️⃣", "3️⃣"][i];
  top3List += `${emojiNumber} *${sliceTitle(v.title, 35)}*\n   👁️ *${v.views}* views | 📊 *${v.engagement.toFixed(1)}%* engaj.\n`;
});

// Constrói a mensagem
let msg = `📊 *ShortBot - Relatório de Desempenho ManoSabio*\n\n`;
msg += `📈 *Status Geral do Canal*:\n`;
msg += `• Total de Vídeos: *${totalVideos}*\n`;
msg += `• Melhor Vídeo: *${sliceTitle(topVideo.title, 40)}* (*${topVideo.views}* views)\n\n`;

msg += `🏆 *TOP 3 Shorts mais Assistidos*:\n${top3List}\n`;

msg += `🔥 *Métricas Médias (TOP 5)*:\n`;
msg += `• Média de Views: *${avgViewsTop5}*\n`;
msg += `• Média de Engajamento: *${avgEngageTop5}%*\n\n`;

msg += `💡 *Sugestão de Temas*:\n`;
msg += `• Rodar \`python main.py --auto 4\` para gerar 4 novos Shorts de forma automática. O motor irá equilibrar 50% de temas vencedores e 50% de novos testes de nicho para expandir sua audiência! 🚀`;

return {
  msg: encodeURIComponent(msg)
};
